import java.util.Arrays;
public final class CapacityShelf {
    private final String[] labels;
    private int size;
    public CapacityShelf(int capacity) {
        if (capacity < 0) throw new IllegalArgumentException("Negative capacity");
        labels = new String[capacity];
    }
    public int size() { return size; }
    private static void validate(String label) {
        if (label == null || label.isEmpty()) throw new IllegalArgumentException("Missing label");
    }
    private int indexOf(String label) {
        for (int i = 0; i < size; i++) if (labels[i].equals(label)) return i;
        return -1;
    }
    public boolean add(String label) {
        validate(label);
        if (indexOf(label) >= 0 || size == labels.length) return false;
        labels[size++] = label;
        return true;
    }
    public boolean remove(String label) {
        validate(label);
        int index = indexOf(label);
        if (index < 0) return false;
        for (int i = index; i < size - 1; i++) labels[i] = labels[i + 1];
        labels[--size] = null;
        return true;
    }
    public String[] snapshot() { return Arrays.copyOf(labels, size); }
}
